import type { ReportKey } from "@/features/reporting/reports/report-definitions";

/**
 * Lazy template imports: each .mrt lands in its own chunk and only loads on
 * the page that renders it. Generated by `pnpm reporting:templates`.
 */
type TemplateModule = Promise<{ default: unknown }>;

export const REPORT_TEMPLATES: Record<ReportKey, () => TemplateModule> = {
  "processed-orders": () => import("./reports/processed-orders.mrt.json"),
  "daily-stock": () => import("./reports/daily-stock.mrt.json"),
  transfers: () => import("./reports/transfers.mrt.json"),
  sales: () => import("./reports/sales.mrt.json"),
  inventory: () => import("./reports/inventory.mrt.json"),
};

export const loadAnalyticsTemplate = (): TemplateModule => import("./dashboards/analytics.mrt.json");
